begin;
select plan(18);
select is(has_table_privilege('anon','public.catalogue_source','select'),false,'source permissions are private');
select is(has_table_privilege('authenticated','public.sale_candidates','select'),false,'candidate inbox is private');
select is(has_function_privilege('anon','public.commit_catalogue(bigint,jsonb)','execute'),false,'browser cannot publish inventory');
select is(has_function_privilege('authenticated','public.finish_daily_run(uuid,jsonb,text,jsonb)','execute'),false,'browser cannot ingest');
select is(has_function_privilege('anon','public.review_sale_candidate(text,text,text,text,text)','execute'),false,'browser cannot review');
select is((public.load_catalogue()->>'version')::bigint,1::bigint,'empty shared catalogue has revision');
select ok(public.commit_catalogue(1,public.load_catalogue()->'tables'),'whole reviewed transaction commits');
select ok(not public.commit_catalogue(1,public.load_catalogue()->'tables'),'stale catalogue cannot overwrite');
select throws_ok($$select public.commit_catalogue(2,'{}')$$,'P0001','Invalid catalogue snapshot','bad snapshot rejected');
select is((public.load_catalogue()->>'version')::bigint,2::bigint,'invalid snapshot did not advance revision');
create temporary table lease as select public.claim_daily_run('test') as id;
select isnt((select id from lease),null::uuid,'claim daily lease');
select is(public.claim_daily_run('overlap'),null::uuid,'second worker cannot overlap');
select is(public.finish_daily_run((select id from lease),'[]','completed','{}'),0,'empty completed batch is valid');
select throws_ok($$select public.finish_daily_run((select id from lease),'[]','completed','{}')$$,'P0001','Missing or expired ingestion lease','finished lease cannot replay');
select lives_ok($$insert into public.sale_candidates(id,source_id,source_key,source_url,fingerprint,payload,checked_at,expires_at) values('candidate-aaaaaaaaaaaaaaaaaaaaaaaa','otofun','otofun:1:post-2','https://www.otofun.net.vn/threads/test.1/#post-2',repeat('a',64),'{"publication_ready":false}',now(),now()+interval '1 day')$$,'candidate staged separately');
select lives_ok($$select public.review_sale_candidate('candidate-aaaaaaaaaaaaaaaaaaaaaaaa',repeat('a',64),'keep','operator','Check original submission next')$$,'review binds exact source revision');
select throws_ok($$select public.review_sale_candidate('candidate-aaaaaaaaaaaaaaaaaaaaaaaa',repeat('b',64),'keep','operator','stale')$$,'P0001','Candidate changed or expired. Reload before reviewing','changed candidate needs new review');
select is((select count(*)::integer from public.catalogue_listing_offer),0,'keeping a lead does not publish inventory');
select * from finish();
rollback;
